code:
// face left (Player slots 5-8)
lda #$01
jsr setFacing

// CLEAR THE TEXT ROWS WITH SPACES
// CLR SCRN RAM above fills $0400 with 0 - right for the collision tags, but in
// the text-mode rows (19-24) screencode 0 shows as @. Overwrite just those
// 240 chars ($06F8-$07E7) with spaces. Rows 0-18 stay 0 = "nothing here".
ldx #$00
lda #$20
ctLoop:
sta $06f8,x
inx
cpx #240
bne ctLoop

// the pluck is not filtered - take voice 1 back out of the filter
lda #$00
sta $d417

// face right (Player slots 0-3)
lda #$00
jsr setFacing

// SPLIT ROW - keep char row 19 blank in BOTH video modes
// The TextMode IRQ fires ON the badline of row 19 (raster 203). The VIC steals
// the bus there, so the mode switch always lands somewhere inside row 19 - never
// in row 18 - and row 19 has to look empty whichever mode is showing it.
//   bitmap side - bitmap row 19 is all zero, so it draws as background
//   text side   - the VIC may still fetch its char codes from the bitmap's
//                 screen RAM ($6000 row 19), so put spaces there ($20)
// $0400 row 19 is already spaces (CLEAR THE TEXT ROWS above). No NOP timing.
ldx #39
lda #$20
srLoop:
sta $62f8,x
dex
bpl srLoop

// SPLIT - bitmap to text with no garbage line
// The IRQ lands somewhere in row 19 with a different delay every frame, and
// the VIC node below writes bank, $D018, $D011 one at a time - the beam drew
// part of a line in each half-switched mode (bitmap from code at $17C0, etc).
// This does the switch in an order where EVERY in-between state reads empty
// memory, so row 19 stays blank whenever the writes land:
//  1  $D018=$8C  bitmap from $6000 - row 19 is $77C0-$78FF   (empty)
//  2  $D011=$1B  text, chars from bank 1 $7800-$7FFF          (empty)
//  3  bank 0     text, chars from $3800-$3FFF                 (empty)
//  4  $D018=$14  ROM chars, screen $0400 - row 19 is spaces
// KEEP $3800-$3FFF and $7700-$7FFF FREE (all zero).
// The VIC node below then writes the same final values again.
lda #$8c
sta $d018
lda #$1b
sta $d011
lda $dd00
and #$fc
ora #$03
sta $dd00
lda #$14
sta $d018
// GREY DOTS - the VIC node also rewrites $D020 then $D021 (6 cycles apart),
// and a colour write flashes one grey pixel where the beam is: a $D020 dot
// only shows over border, a $D021 dot only over background. 54 cycles puts
// $D020 at x 297-337 (inside the 40 columns) and $D021 at x 345-385 (border)
// on the next row 19 line, so neither shows. Tuned in VICE (5 cycle jitter) -
// change any code above or the VIC node and re-check this.
ldx #$0a       // 2 + 10 x 5 - 1 = 51 cycles
gdDelay:
dex
bne gdDelay
bit $00        // +3 = 54

// SHEET TAGS OFF - the source sheet lives in the BITMAP asset at $8000 now,
// not on screen. BMPBDR_TAGS ($CC00) rows 0-1 hold the tags of the source
// cells (house = solid etc.) so the builder above can copy them onto the
// field; once it has, clear them so the (now plain) top two rows of the field
// are walkable and do not act like the sheet's house.
ldx #79           // 2 rows x 40 tags
lda #$00
stoLoop:
sta $cc00,x       // BMPBDR_TAGS
dex
bpl stoLoop
